\section{Preliminaries} \label{sec:preliminaries}
\subsection{Probability distributions}
\begin{definition} \label{def:smooth-pair-of-distributions}
    Let \((P,Q)\) be an (ordered) pair of probability distributions supported on a set \(\Omega\). We say that \((P,Q)\) are \((A,\alpha)\)-smooth if for every \(v \in A\) it holds that \(\alpha \Prob[P]{v} \leq \Prob[Q]{v}\). We say that \((P,Q)\) are \(\alpha\)-smooth if they are \((\Omega,\alpha)\)-smooth.    

\end{definition}

\begin{claim}\label{claim:property-of-smooth-dist}
    Let \((P,Q)\) be \((A,\alpha)\) smooth. Then for every \(B \subseteq A\) it holds that \(\alpha \Prob[P]{B} \leq \Prob[Q]{B}\). \(\qed\)
\end{claim}

\subsection{Expander graphs}
Let \(G=(V,E)\) be a graph and let \(\mu:E \to (0,1]\) be a probability distribution. The distribution on the edges extends naturally to a distribution on the vertices where probability of a vertex is \(\mu(v) = \frac{1}{2} \sum_{e \ni v} \mu(e)\) (we abuse notation and denote this distribution \(\mu\) as well). 

We say that \(G\) is an \(\eta\)-edge expander if for every subset \(S \subseteq V\), \(S \ne \emptyset, V\) it holds that
\[\Prob[uv \in E]{u \in S,v \in V \setminus S} \geq \eta \prob{S} \prob{V \setminus S}.\]

\subsection{Majority and expansion}
Let \(G=(V,E)\) be a graph and let \(g:V \to \set{1,2,\dots,n}\) be some function. Denote by \(S_i = \sett{v \in V}{g(v)=i}\). The majority assignment \(maj(g) \in \set{1,2,\dots,n}\) is the \(i\) such that \(\prob{S_i}\) is largest (ties broken arbitrarily).

\begin{claim} \label{claim:expander-and-majority}
    Let \(G\) be an \(\eta\)-edge expander. Let \(S_1,S_2,\dots,S_m\) be a partition of the vertices of \(V\) as above. Assume that \(\Prob[uv \in E]{\exists i \; u \in S_i \ve v \notin S_i} \leq \varepsilon\). Then there exists \(i\) such that \(\prob{S_i} \geq 1- \frac{\varepsilon}{\eta}\).

    Stated differently, for every \(g:V \to \set{1,2,\dots,n}\), \(\Prob[v]{g(v) \ne maj(g)} \leq \frac{\Prob[uv \in E]{g(u) \ne g(v)}}{\eta}\).
\end{claim}

\subsection{Local spectral expanders}

A pure \(d\)-dimensional simplicial complex \(X\) is a hypergraph that consists of an arbitrary collection of sets of size \((d+1)\) together with all their subsets. The sets of size \(i+1\) in \(X\) are denoted by \(X(i)\). The vertices of \(X\) are denoted by \(X(0)\) (we identify between a vertex \(v\) and its singleton \(\set{v}\)). We will sometimes omit set brackets and write for example \(uvw\in X(2)\) instead of \(\set{u,v,w}\in X(2)\). As a convention \(X(-1) = \set{\emptyset}\).
Let \(X\) be a \(d\)-dimensional simplicial complex. Let \(k \leq d\). We denote the set of oriented \(k\)-faces in \(X\) by \(\dir{X}(k) = \sett{(v_0,v_1,...,v_k)}{\set{v_0,v_1,...,v_k} \in X(k)}\).

\subsubsection*{Probability over simplicial complexes}
Let \(X\) be a simplicial complex and let \(\Pr_d:X(d)\to (0,1]\) be a density function on \(X(d)\) (that is, \(\sum_{s \in X(d)}\Pr_d(s)=1\)). This density function induces densities on lower level faces \(\Pr_k:X(k)\to (0,1]\) by \(\Pr_k(t) = \frac{1}{\binom{d+1}{k+1}}\sum_{s \in X(d),s \supset t} \Pr_d(s)\). We can also define a probability over directed faces, where we choose an ordering uniformly at random. Namely, for \(s\in \dir{X}(k)\), \(\Pr_k(s) = \frac{1}{(k+1)!}\Pr_k(set(s))\) (where \(set(s)\) is the set of vertices participating in \(s\)). When clear from the context, we omit the level of the faces, and just write \(\Pr[T]\) or \(\Prob[t \in X(k)]{T}\) for a set \(T \subseteq X(k)\).

\subsection{Coboundary and Cosystolic Expansion}

Let \(X\) be a \(d\)-dimensional simplicial complex for \(d \geq 2\) and let \(\Gamma\) be any group. For \(i=-1,0\) let 
\(C^i(X,\Gamma) = \set{f:X(i) \to \Gamma}\). We sometimes identify \(C^{-1}(X,\Gamma) \cong \Gamma\). For \(i=1,2\) let
\[C^1(X,\Gamma) = \sett{f:\dir{X}(1) \to \Gamma}{f(u,v)=f(v,u)^{-1}}\]
and
\[C^2(X,\Gamma) = \sett{f:\dir{X}(i) \to \Gamma}{\forall \pi \in Sym(3), (v_0,v_1,v_2) \in \dir{X}(2) \; f(v_{\pi(0)},v_{\pi(1)},v_{\pi(2)}) = f(v_0,v_1,v_2)^{\sign(\pi)}}.\]
be the spaces of so-called {\em anti-symmetric} functions on edges and triangles. For \(i=-1,0,1\) we define functions \(\coboundary_i : C^i(X,\Gamma) \to C^{i+1}(X,\Gamma)\) by
\begin{enumerate}
    \item \(\coboundary_{-1} h (v) = h(\emptyset)\).
    \item \(\coboundary_{0} h (v,u) = h(v)h(u)^{-1}\).
    \item \(\coboundary_{1} h (v,u,w) = h(v,u)h(u,w)h(w,v)\).
\end{enumerate}
Let \(Id = Id_i \in C^i(X,\Gamma)\) be the function that always outputs the identity element. It is easy to check that \(\coboundary_{i+1} \circ \coboundary_i h \equiv Id_{i+2}\) for all \(i=-1,0\) and \(h \in C^{i}(X,\Gamma)\). Thus we denote by
\[Z^i(X,\Gamma) = \ker \coboundary_{i} \subseteq C^i(X,\Gamma),\]
\[B^i(X,\Gamma) = \Img \coboundary_{i-1} \subseteq C^i(X,\Gamma),\]
and have that \(B^i(X,\Gamma) \subseteq Z^i(X,\Gamma)\). 

Henceforth, when the dimension $i$ of the cochain $f$ is clear from the context we denote $\coboundary_i f$ by $\coboundary f$.

Let \(f,g \in C^i(X,\Gamma)\). Then
\begin{equation} \label{eq:def-of-dist}
    \dist(f,g) = \Prob[s \in \dir{X}(i)]{f(s) \ne g(s)}.
\end{equation}
We also denote the weight of the function \(\wt(f) = \dist(f,Id)\).

\begin{definition}[Cosystolic expansion] \label{def:def-of-cosyst-exp}
    Let \(X\) be a \(d\)-dimensional simplicial complex for \(d \geq 2\). Let \(\beta >0\). We say that \(X\) is a \(\beta\)-cosystolic expander if for every group \(\Gamma\), and every \(f \in C^1(X,\Gamma)\) there exists some \(g \in Z^1(X,\Gamma)\) such that
    \begin{equation} \label{eq:def-of-cosyst-exp}
        \beta \dist(f,g) \leq \wt(\coboundary f).
    \end{equation}
    In this case we denote \(h^1(X) \geq \beta\).
\end{definition}

\begin{definition}[Coboundary expansion] \label{def:def-of-cob-exp}
    Let \(X\) be a \(d\)-dimensional simplicial complex for \(d \geq 2\). Let \(\beta >0\). We say that \(X\) is a \(\beta\)-coboundary expander if it is a \(\beta\)-cosystolic expander and in addition \(Z^1(X,\Gamma) = B^1(X,\Gamma)\) for every group \(\Gamma\).
\end{definition}

\section{The GK decomposition} \label{sec:gk-decomposition}

Recall that for a simplicial complex with multi-edges \(\set{u,v}_i\), we denote a triangle \(\set{u,v,w}_{i,j,k}\) to be the triangle whose vertices are \(u,v,w\) and whose edges are \(\set{u,v}_i, \set{v,w}_j, \set{w,u}_k\).

\begin{definition}[agreement complex] \label{def:agreement-complex}
Let \(X\) be a \(2\)-dimensional simplicial complex and let \(\mathcal{Y} = \set{Y_i}_{i \in I}\) be a family of sub-complexes of \(X\). A complex \(X\) is a agreement complex with respect to \(X,\mathcal{Y}\) if,
\begin{enumerate} 
    \item \(\A(0) = \mathcal{Y}\).
    \item \(\A(1) \subseteq \sett{\set{Y_i,Y_j}_{v}}{v \in Y_i(0) \cap Y_j(0)}\).
    \item \(\A(2) \subseteq \sett{\set{Y_i,Y_j,Y_k}_{v_1,v_2,v_3}}{\set{v_1,v_2,v_3} \in X(2)}\).
\end{enumerate}
\end{definition}

\begin{definition}[GK-decomposition]
    A GK-decomposition of \(X\) is a tuple \((\mathcal{Y},\A,\nu,\pi)\) such that 
\begin{enumerate}
    \item \(\mathcal{Y} = \set{Y_i}_{i \in I}\), are such that \(Y_i \subseteq X\) are pure sub complexes.
    \item \(\A\) is an agreement complex with respect to \(\mathcal{Y}\) whose distribution over triangles is \(\pi\).
    \item \(\nu\) is a distribution over tuples \((\set{u,v,w},Y_i)\) such that \(\set{u,v,w} \in Y_i\).
\end{enumerate}
\end{definition}

For a distribution \(\nu\) and \(i=0,1,2\) we define \(\nu_i\) to be the marginal that just outputs the \(i\)-face chosen by \(\nu\). E.g. for \(i=1\) we just take a random edge inside the triangle in the tuple chosen. We also denote by \(\nu_{i,y}\) the marginal that outputs the \(i\)-face chosen by \(\nu\) along with the sub complex \(Y_i\). Furthermore, we denote by \(\nu_y\) the marginal distribution of \(\nu\) over \(\mathcal{Y}\). Finally, we denote by \(\nu|_{Y_i}\) to be \(\nu\) conditioned on \(Y_i\) being the chosen subcomplex.

For a distribution \(\pi\) supported over \(\A(2)\) we also need similar notation. Let \(i=0,1,2\). The distribution \(\pi_i\) is the marginal distribution that outputs a \(i\)-face that is a sub face of the labels of the chosen triangle. E.g. for \(i=1\), if \(\set{Y_i,Y_j,Y_k}_{u,v,w} \sim \pi\) then \(\pi_1\) outputs one of three edges \(uv,vw,uw \in X(1)\). For \(i=1\) we denote by \(\pi_{1,y}\) the distribution that outputs \((uv,Y_j)\). That is, if \(\set{Y_i,Y_j,Y_k}_{u,v,w} \sim \pi\), then \(\pi_{1,y}\) outputs a random edge in \(\set{u,v,w}\), along with the \(Y_j\) such that \(\set{Y_i,Y_j}_u, \set{Y_j,Y_k}_v\) participate in the triangle. Finally, \(\pi_{0,y}\) is the marginal of \(\pi_{1,y}\) that samples one vertex of the sampled edge uniformly at random. I.e. if \((uv,Y_j) \sim \pi_{1,y}\) then \(\pi_{0,y}\) samples either \((u,Y_j)\) or \((v,Y_j)\).

\begin{definition}[Local graph] \label{def:local-graph}
    Let \(\A\) be an agreement complex as above. For every \(v \in \A(0)\) the local graph \(\A^v\) is a graph whose vertices are all \(Y_i \ni v\). The edges are all \(Y_i \sim Y_j\) such that \(Y_i \cap Y_j \ni v\), where we choose an edge according to the distribution of the agreement complex, given that it was labeled by \(v\).
\end{definition}
