\begin{theorem} \label{thm:decomposition-to-coboundary-expanders}
Let \(X\) be a \(2\)-dimensional simplicial complex and let \((\mathcal{Y},\A,\nu,\pi)\) be a GK-decomposition. Let \(\alpha, \beta, \gamma, \eta > 0\). Assume that the following holds.
\begin{enumerate}
    \item Every \(Y_i\) is a coboundary expander with \(h^1(Y_i)\geq \beta\), with respect to the distribution \(\nu|_{Y_i}\).
    \item \(h^1(\A) \geq \gamma\).
    \item Let \(A \subseteq X(0)\) be the set of vertices that are contained in at least two \(Y_i\)'s. For every \(v \in A\), the local graph \(\A^v\) is a \(\eta\)-edge expander.
    \item Recall that \(\mu_i\) is the distribution of \(i\)-faces in \(X\). Then the following relations between distributions hold:
    \begin{enumerate}
        \item \((\nu_2,\mu_2)\) and \((\pi_2,\mu_2)\) are \(\alpha\)-smooth\footnote{as in \pref{def:smooth-pair-of-distributions}.}.
        \item \((\mu_1, \nu_1)\) are \(\alpha\)-smooth.
        \item \((\nu_{0,y},\pi_{0,y})\) are \((A_Y,\alpha)\)-smooth. Here \(A_Y\) are all \((v,Y_i)\) such that \(v \in Y_i\) and \(v \in A\).        
        \item \((\pi_{1,y},\nu_{1,y})\) are \(\alpha\)-smooth.
    \end{enumerate}
\begin{figure}
    \centering
    \begin{tikzcd}
	\pi~ && ~\nu~ &&& ~\mu \\
	{X(2)\hbox{ and }\A(2)} && {X\circ(Y_1,\ldots,Y_m)} &&& X
	\arrow[leftrightarrow,from=1-1, to=1-3]
	\arrow[leftrightarrow, from=1-3, to=1-6]
